// Aggregate all sources for baseline generation
const product = $input.item(0).json.product;
const currentDocs = $input.item(1).json.documents || [];
const activeOverrides = $input.item(2).json.overrides || [];
const recentQA = $input.item(3).json.qa_pairs || [];
const temporalUpdates = $input.item(4).json.updates || [];
const offboardingKnowledge = $input.item(5).json.knowledge || [];

return [{
  json: {
    product: product,
    baseline_id: `bp-${product}-${Date.now()}`,
    sources: {
      current_documents: currentDocs.map(d => ({
        doc_id: d.doc_id,
        type: d.document_type,
        version: d.version,
        content_summary: d.summary
      })),
      active_overrides: activeOverrides.map(o => ({
        message_id: o.message_id,
        content: o.content,
        affected_docs: o.override_analysis.documents,
        approved_date: o.approved_date
      })),
      recent_qa: recentQA.map(qa => ({
        question: qa.content,
        answer: qa.answer,
        frequency: qa.frequency || 1
      })),
      temporal_updates: temporalUpdates.map(u => ({
        update_id: u.message_id,
        content: u.content,
        processed_date: u.processed_date
      })),
      offboarding_insights: offboardingKnowledge.map(k => ({
        source_user: k.user_id,
        insights: k.undocumented_knowledge,
        validated: true
      }))
    },
    created_date: new Date().toISOString()
  }
}];

