// Parse baseline and check for conflicts
const response = $input.first().json;
const baseline = JSON.parse(response.content[0].text);
const sourceData = $input.item(1).json;

const hasUnresolvedConflicts = baseline.unresolved_conflicts && baseline.unresolved_conflicts.length > 0;
const lowConfidenceSections = baseline.sections.filter(s => s.confidence < 0.7);

return [{
  json: {
    baseline_id: sourceData.baseline_id,
    product: sourceData.product,
    baseline_content: baseline,
    requires_review: hasUnresolvedConflicts || lowConfidenceSections.length > 0,
    review_items: {
      unresolved_conflicts: baseline.unresolved_conflicts || [],
      low_confidence_sections: lowConfidenceSections.map(s => s.section_id)
    },
    sources: sourceData.sources,
    created_date: sourceData.created_date
  }
}];

